#include <cmath>

// norm_cdf(x) is defined for you.
double norm_quantile(double p) {
    if (std::isnan(p) || p < 0 || p > 1) return NAN;
    if (p == 0) return -INFINITY;
    if (p == 1) return INFINITY;
    double lo = -10, hi = 10;
    while (hi - lo > 1e-10) {
        double mid = 0.5 * (lo + hi);
        if (norm_cdf(mid) < p) lo = mid;
        else hi = mid;
    }
    return 0.5 * (lo + hi);
}
